-- Additive target manifest coordination. No routing or deployment is installed.
-- The installer must consume this entire forward file in its supported transaction.
CREATE TABLE release_seoul_target_manifests(
 generation INTEGER NOT NULL CONSTRAINT target_manifests_pk PRIMARY KEY,
 manifest_id TEXT NOT NULL CONSTRAINT target_manifest_id_uq UNIQUE,
 expected_generation INTEGER CONSTRAINT target_manifest_predecessor_uq UNIQUE,
 manifest_bytes TEXT NOT NULL,manifest_sha256 TEXT NOT NULL,set_sha256 TEXT NOT NULL,
 desired_count INTEGER NOT NULL,operator_reference TEXT NOT NULL,published_at INTEGER NOT NULL,
 CONSTRAINT target_manifest_predecessor_fk FOREIGN KEY(expected_generation) REFERENCES release_seoul_target_manifests(generation),
 CONSTRAINT target_manifest_shape_ck CHECK((typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND (typeof(manifest_id)='text' AND length(CAST(manifest_id AS BLOB))=36 AND length(manifest_id)=36 AND substr(manifest_id,9,1)='-' AND substr(manifest_id,14,1)='-' AND substr(manifest_id,19,1)='-' AND substr(manifest_id,24,1)='-' AND length(replace(manifest_id,'-',''))=32 AND replace(manifest_id,'-','') NOT GLOB '*[^0-9a-f]*') AND (expected_generation IS NULL AND generation=1 OR expected_generation IS NOT NULL AND (typeof(expected_generation)='integer' AND expected_generation BETWEEN 1 AND 9007199254740991) AND expected_generation<9007199254740991 AND generation=expected_generation+1)
 AND typeof(manifest_bytes)='text' AND length(CAST(manifest_bytes AS BLOB)) BETWEEN 1 AND 134539 AND json_valid(manifest_bytes) AND json_type(manifest_bytes)='object'
 AND (typeof(manifest_sha256)='text' AND length(CAST(manifest_sha256 AS BLOB))=64 AND length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*') AND (typeof(set_sha256)='text' AND length(CAST(set_sha256 AS BLOB))=64 AND length(set_sha256)=64 AND set_sha256 NOT GLOB '*[^0-9a-f]*') AND typeof(desired_count)='integer' AND desired_count BETWEEN 0 AND 1024 AND (typeof(operator_reference)='text' AND length(CAST(operator_reference AS BLOB)) BETWEEN 1 AND 256 AND length(CAST(operator_reference AS BLOB))=length(operator_reference) AND substr(operator_reference,1,1) GLOB '[A-Za-z0-9]' AND operator_reference NOT GLOB '*[^A-Za-z0-9._:-]*') AND (typeof(published_at)='integer' AND published_at BETWEEN 0 AND 9007199254740991)
 AND json_type(manifest_bytes,'$.version')='integer' AND json_extract(manifest_bytes,'$.version')=1
 AND json_extract(manifest_bytes,'$.manifestId')=manifest_id AND json_extract(manifest_bytes,'$.expectedGeneration') IS expected_generation AND json_extract(manifest_bytes,'$.operatorReference')=operator_reference
 AND json_type(manifest_bytes,'$.spaceIds')='array' AND json_array_length(manifest_bytes,'$.spaceIds')=desired_count
 AND manifest_bytes=json_object('version',1,'manifestId',manifest_id,'expectedGeneration',expected_generation,'operatorReference',operator_reference,'spaceIds',json_extract(manifest_bytes,'$.spaceIds')))
);
CREATE TABLE release_seoul_target_manifest_members(
 generation INTEGER NOT NULL,space_id TEXT NOT NULL,ordinal INTEGER NOT NULL,
 CONSTRAINT target_manifest_members_pk PRIMARY KEY(generation,space_id),CONSTRAINT target_manifest_member_order_uq UNIQUE(generation,ordinal),
 CONSTRAINT target_manifest_members_generation_fk FOREIGN KEY(generation) REFERENCES release_seoul_target_manifests(generation),
 CONSTRAINT target_manifest_member_shape_ck CHECK((typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND (typeof(space_id)='text' AND length(CAST(space_id AS BLOB)) BETWEEN 1 AND 128 AND length(CAST(space_id AS BLOB))=length(space_id) AND substr(space_id,1,1) GLOB '[A-Za-z0-9]' AND space_id NOT GLOB '*[^A-Za-z0-9._:-]*') AND typeof(ordinal)='integer' AND ordinal BETWEEN 1 AND 1024)
);
CREATE TABLE release_seoul_target_manifest_control(
 singleton INTEGER NOT NULL CONSTRAINT target_manifest_control_pk PRIMARY KEY,current_generation INTEGER,
 CONSTRAINT target_manifest_control_generation_fk FOREIGN KEY(current_generation) REFERENCES release_seoul_target_manifests(generation),
 CONSTRAINT target_manifest_control_shape_ck CHECK(typeof(singleton)='integer' AND singleton=1 AND (current_generation IS NULL OR (typeof(current_generation)='integer' AND current_generation BETWEEN 1 AND 9007199254740991)))
);
INSERT INTO release_seoul_target_manifest_control(singleton,current_generation) VALUES(1,NULL);
CREATE TABLE release_seoul_target_manifest_pages(
 generation INTEGER NOT NULL,phase TEXT NOT NULL,page_no INTEGER NOT NULL,after_space_id TEXT,last_space_id TEXT,row_count INTEGER NOT NULL,cumulative_count INTEGER NOT NULL,terminal INTEGER NOT NULL,observed_at INTEGER NOT NULL,
 CONSTRAINT target_manifest_pages_pk PRIMARY KEY(generation,phase,page_no),CONSTRAINT target_manifest_pages_generation_fk FOREIGN KEY(generation) REFERENCES release_seoul_target_manifests(generation),
 CONSTRAINT target_manifest_page_shape_ck CHECK((typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND phase IN ('desired','omitted','verify') AND (typeof(page_no)='integer' AND page_no BETWEEN 1 AND 9007199254740991) AND (after_space_id IS NULL OR (typeof(after_space_id)='text' AND length(CAST(after_space_id AS BLOB)) BETWEEN 1 AND 128 AND length(CAST(after_space_id AS BLOB))=length(after_space_id) AND substr(after_space_id,1,1) GLOB '[A-Za-z0-9]' AND after_space_id NOT GLOB '*[^A-Za-z0-9._:-]*')) AND (last_space_id IS NULL OR (typeof(last_space_id)='text' AND length(CAST(last_space_id AS BLOB)) BETWEEN 1 AND 128 AND length(CAST(last_space_id AS BLOB))=length(last_space_id) AND substr(last_space_id,1,1) GLOB '[A-Za-z0-9]' AND last_space_id NOT GLOB '*[^A-Za-z0-9._:-]*'))
 AND typeof(row_count)='integer' AND row_count BETWEEN 0 AND 32 AND (typeof(cumulative_count)='integer' AND cumulative_count BETWEEN 0 AND 9007199254740991) AND typeof(terminal)='integer' AND terminal IN (0,1) AND (typeof(observed_at)='integer' AND observed_at BETWEEN 0 AND 9007199254740991)
 AND (terminal=1 OR row_count=32) AND (row_count>0 AND last_space_id IS NOT NULL OR row_count=0 AND page_no=1 AND terminal=1 AND last_space_id IS NULL AND after_space_id IS NULL AND cumulative_count=0)
 AND (page_no=1 AND after_space_id IS NULL OR page_no>1 AND after_space_id IS NOT NULL) AND (after_space_id IS NULL OR last_space_id>after_space_id))
);
CREATE TABLE release_seoul_target_manifest_steps(
 generation INTEGER NOT NULL,space_id TEXT NOT NULL,command_id TEXT NOT NULL,expected_revision INTEGER,selected INTEGER NOT NULL,operator_reference TEXT NOT NULL,page_phase TEXT NOT NULL,page_no INTEGER NOT NULL,
 CONSTRAINT target_manifest_steps_pk PRIMARY KEY(generation,space_id),CONSTRAINT target_manifest_step_command_uq UNIQUE(command_id),
 CONSTRAINT target_manifest_steps_generation_fk FOREIGN KEY(generation) REFERENCES release_seoul_target_manifests(generation),CONSTRAINT target_manifest_step_source_fk FOREIGN KEY(expected_revision) REFERENCES release_seoul_authority_changes(revision),
 CONSTRAINT target_manifest_step_page_fk FOREIGN KEY(generation,page_phase,page_no) REFERENCES release_seoul_target_manifest_pages(generation,phase,page_no),
 CONSTRAINT target_manifest_step_shape_ck CHECK((typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND (typeof(space_id)='text' AND length(CAST(space_id AS BLOB)) BETWEEN 1 AND 128 AND length(CAST(space_id AS BLOB))=length(space_id) AND substr(space_id,1,1) GLOB '[A-Za-z0-9]' AND space_id NOT GLOB '*[^A-Za-z0-9._:-]*') AND (typeof(command_id)='text' AND length(CAST(command_id AS BLOB))=36 AND length(command_id)=36 AND substr(command_id,9,1)='-' AND substr(command_id,14,1)='-' AND substr(command_id,19,1)='-' AND substr(command_id,24,1)='-' AND length(replace(command_id,'-',''))=32 AND replace(command_id,'-','') NOT GLOB '*[^0-9a-f]*') AND (expected_revision IS NULL OR (typeof(expected_revision)='integer' AND expected_revision BETWEEN 1 AND 9007199254740991)) AND typeof(selected)='integer' AND selected IN (0,1) AND (typeof(operator_reference)='text' AND length(CAST(operator_reference AS BLOB)) BETWEEN 1 AND 256 AND length(CAST(operator_reference AS BLOB))=length(operator_reference) AND substr(operator_reference,1,1) GLOB '[A-Za-z0-9]' AND operator_reference NOT GLOB '*[^A-Za-z0-9._:-]*') AND page_phase IN ('desired','omitted') AND selected=CASE WHEN page_phase='desired' THEN 1 ELSE 0 END AND (typeof(page_no)='integer' AND page_no BETWEEN 1 AND 9007199254740991))
);
CREATE TABLE release_seoul_target_manifest_seals(
 generation INTEGER NOT NULL CONSTRAINT target_manifest_seals_pk PRIMARY KEY,desired_terminal_page INTEGER NOT NULL,omitted_terminal_page INTEGER NOT NULL,desired_count INTEGER NOT NULL,omitted_count INTEGER NOT NULL,total_count INTEGER NOT NULL,sealed_at INTEGER NOT NULL,
 CONSTRAINT target_manifest_seals_generation_fk FOREIGN KEY(generation) REFERENCES release_seoul_target_manifests(generation),
 CONSTRAINT target_manifest_seal_shape_ck CHECK((typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND (typeof(desired_terminal_page)='integer' AND desired_terminal_page BETWEEN 1 AND 9007199254740991) AND (typeof(omitted_terminal_page)='integer' AND omitted_terminal_page BETWEEN 1 AND 9007199254740991) AND (typeof(desired_count)='integer' AND desired_count BETWEEN 0 AND 9007199254740991) AND desired_count<=1024 AND (typeof(omitted_count)='integer' AND omitted_count BETWEEN 0 AND 9007199254740991) AND (typeof(total_count)='integer' AND total_count BETWEEN 0 AND 9007199254740991) AND desired_count<=9007199254740991-omitted_count AND total_count=desired_count+omitted_count AND (typeof(sealed_at)='integer' AND sealed_at BETWEEN 0 AND 9007199254740991))
);
CREATE TABLE release_seoul_target_manifest_completions(
 generation INTEGER NOT NULL CONSTRAINT target_manifest_completions_pk PRIMARY KEY,manifest_sha256 TEXT NOT NULL,set_sha256 TEXT NOT NULL,verified_terminal_page INTEGER NOT NULL,step_count INTEGER NOT NULL,completed_at INTEGER NOT NULL,
 CONSTRAINT target_manifest_completions_generation_fk FOREIGN KEY(generation) REFERENCES release_seoul_target_manifests(generation),
 CONSTRAINT target_manifest_completion_shape_ck CHECK((typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND (typeof(manifest_sha256)='text' AND length(CAST(manifest_sha256 AS BLOB))=64 AND length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*') AND (typeof(set_sha256)='text' AND length(CAST(set_sha256 AS BLOB))=64 AND length(set_sha256)=64 AND set_sha256 NOT GLOB '*[^0-9a-f]*') AND (typeof(verified_terminal_page)='integer' AND verified_terminal_page BETWEEN 1 AND 9007199254740991) AND (typeof(step_count)='integer' AND step_count BETWEEN 0 AND 9007199254740991) AND (typeof(completed_at)='integer' AND completed_at BETWEEN 0 AND 9007199254740991))
);
CREATE TABLE release_seoul_target_manifest_cancellations(
 generation INTEGER NOT NULL CONSTRAINT target_manifest_cancellations_pk PRIMARY KEY,cancellation_id TEXT NOT NULL CONSTRAINT target_manifest_cancellation_id_uq UNIQUE,operator_reference TEXT NOT NULL,cancelled_at INTEGER NOT NULL,
 CONSTRAINT target_manifest_cancellations_generation_fk FOREIGN KEY(generation) REFERENCES release_seoul_target_manifests(generation),
 CONSTRAINT target_manifest_cancellation_shape_ck CHECK((typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND (typeof(cancellation_id)='text' AND length(CAST(cancellation_id AS BLOB))=36 AND length(cancellation_id)=36 AND substr(cancellation_id,9,1)='-' AND substr(cancellation_id,14,1)='-' AND substr(cancellation_id,19,1)='-' AND substr(cancellation_id,24,1)='-' AND length(replace(cancellation_id,'-',''))=32 AND replace(cancellation_id,'-','') NOT GLOB '*[^0-9a-f]*') AND (typeof(operator_reference)='text' AND length(CAST(operator_reference AS BLOB)) BETWEEN 1 AND 256 AND length(CAST(operator_reference AS BLOB))=length(operator_reference) AND substr(operator_reference,1,1) GLOB '[A-Za-z0-9]' AND operator_reference NOT GLOB '*[^A-Za-z0-9._:-]*') AND (typeof(cancelled_at)='integer' AND cancelled_at BETWEEN 0 AND 9007199254740991))
);
CREATE TABLE release_seoul_target_manifest_attempt(
 token TEXT NOT NULL CONSTRAINT target_manifest_attempt_pk PRIMARY KEY,operation TEXT NOT NULL,manifest_id TEXT NOT NULL,generation INTEGER NOT NULL,expected_generation INTEGER,
 input_bytes TEXT,manifest_sha256 TEXT,set_sha256 TEXT,phase TEXT,page_no INTEGER,after_space_id TEXT,
 command_id TEXT,space_id TEXT,expected_revision INTEGER,selected INTEGER,operator_reference TEXT,cancellation_id TEXT,
 observed_generation INTEGER,decided_at INTEGER NOT NULL,
 CONSTRAINT target_manifest_attempt_shape_ck CHECK((typeof(token)='text' AND length(CAST(token AS BLOB))=36 AND length(token)=36 AND substr(token,9,1)='-' AND substr(token,14,1)='-' AND substr(token,19,1)='-' AND substr(token,24,1)='-' AND length(replace(token,'-',''))=32 AND replace(token,'-','') NOT GLOB '*[^0-9a-f]*') AND operation IN ('publish','page','seal','apply','verify','complete','cancel') AND (typeof(manifest_id)='text' AND length(CAST(manifest_id AS BLOB))=36 AND length(manifest_id)=36 AND substr(manifest_id,9,1)='-' AND substr(manifest_id,14,1)='-' AND substr(manifest_id,19,1)='-' AND substr(manifest_id,24,1)='-' AND length(replace(manifest_id,'-',''))=32 AND replace(manifest_id,'-','') NOT GLOB '*[^0-9a-f]*') AND (typeof(generation)='integer' AND generation BETWEEN 1 AND 9007199254740991) AND (expected_generation IS NULL OR (typeof(expected_generation)='integer' AND expected_generation BETWEEN 1 AND 9007199254740991)) AND (observed_generation IS NULL OR (typeof(observed_generation)='integer' AND observed_generation BETWEEN 1 AND 9007199254740991)) AND (typeof(decided_at)='integer' AND decided_at BETWEEN 0 AND 9007199254740991)
 AND (operation='publish' AND input_bytes IS NOT NULL AND manifest_sha256 IS NOT NULL AND set_sha256 IS NOT NULL AND (typeof(manifest_sha256)='text' AND length(CAST(manifest_sha256 AS BLOB))=64 AND length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*') AND (typeof(set_sha256)='text' AND length(CAST(set_sha256 AS BLOB))=64 AND length(set_sha256)=64 AND set_sha256 NOT GLOB '*[^0-9a-f]*') OR operation<>'publish' AND manifest_sha256 IS NULL AND set_sha256 IS NULL AND expected_generation IS NULL)
 AND (operation IN ('publish','page','verify') AND typeof(input_bytes)='text' AND length(CAST(input_bytes AS BLOB)) BETWEEN 2 AND 524288 AND json_valid(input_bytes) OR operation NOT IN ('publish','page','verify') AND input_bytes IS NULL)
 AND (operation IN ('page','verify') AND phase IN ('desired','omitted','verify') AND phase=CASE WHEN operation='verify' THEN 'verify' ELSE phase END AND (operation<>'page' OR phase<>'verify') AND (typeof(page_no)='integer' AND page_no BETWEEN 1 AND 9007199254740991) AND (after_space_id IS NULL OR (typeof(after_space_id)='text' AND length(CAST(after_space_id AS BLOB)) BETWEEN 1 AND 128 AND length(CAST(after_space_id AS BLOB))=length(after_space_id) AND substr(after_space_id,1,1) GLOB '[A-Za-z0-9]' AND after_space_id NOT GLOB '*[^A-Za-z0-9._:-]*')) OR operation NOT IN ('page','verify') AND phase IS NULL AND page_no IS NULL AND after_space_id IS NULL)
 AND (operation='apply' AND (typeof(command_id)='text' AND length(CAST(command_id AS BLOB))=36 AND length(command_id)=36 AND substr(command_id,9,1)='-' AND substr(command_id,14,1)='-' AND substr(command_id,19,1)='-' AND substr(command_id,24,1)='-' AND length(replace(command_id,'-',''))=32 AND replace(command_id,'-','') NOT GLOB '*[^0-9a-f]*') AND (typeof(space_id)='text' AND length(CAST(space_id AS BLOB)) BETWEEN 1 AND 128 AND length(CAST(space_id AS BLOB))=length(space_id) AND substr(space_id,1,1) GLOB '[A-Za-z0-9]' AND space_id NOT GLOB '*[^A-Za-z0-9._:-]*') AND (expected_revision IS NULL OR (typeof(expected_revision)='integer' AND expected_revision BETWEEN 1 AND 9007199254740991)) AND typeof(selected)='integer' AND selected IN (0,1) OR operation<>'apply' AND command_id IS NULL AND space_id IS NULL AND expected_revision IS NULL AND selected IS NULL)
 AND (operation IN ('apply','cancel') AND (typeof(operator_reference)='text' AND length(CAST(operator_reference AS BLOB)) BETWEEN 1 AND 256 AND length(CAST(operator_reference AS BLOB))=length(operator_reference) AND substr(operator_reference,1,1) GLOB '[A-Za-z0-9]' AND operator_reference NOT GLOB '*[^A-Za-z0-9._:-]*') OR operation NOT IN ('apply','cancel') AND operator_reference IS NULL)
 AND (operation='cancel' AND (typeof(cancellation_id)='text' AND length(CAST(cancellation_id AS BLOB))=36 AND length(cancellation_id)=36 AND substr(cancellation_id,9,1)='-' AND substr(cancellation_id,14,1)='-' AND substr(cancellation_id,19,1)='-' AND substr(cancellation_id,24,1)='-' AND length(replace(cancellation_id,'-',''))=32 AND replace(cancellation_id,'-','') NOT GLOB '*[^0-9a-f]*') OR operation<>'cancel' AND cancellation_id IS NULL))
);
CREATE INDEX release_seoul_targets_selected_space ON release_seoul_targets(space_id) WHERE selected=1;
CREATE INDEX target_manifest_steps_page ON release_seoul_target_manifest_steps(generation,page_phase,page_no,space_id);
CREATE INDEX target_manifest_steps_expected_source ON release_seoul_target_manifest_steps(expected_revision);

CREATE TRIGGER target_manifests_occupied BEFORE INSERT ON release_seoul_target_manifests WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifests WHERE generation=NEW.generation OR manifest_id=NEW.manifest_id OR expected_generation=NEW.expected_generation) BEGIN SELECT RAISE(ABORT,'manifest durable identity occupied'); END;
CREATE TRIGGER target_manifests_immutable BEFORE UPDATE ON release_seoul_target_manifests BEGIN SELECT RAISE(ABORT,'manifest durable row immutable'); END;
CREATE TRIGGER target_manifests_retained BEFORE DELETE ON release_seoul_target_manifests BEGIN SELECT RAISE(ABORT,'manifest durable row retained'); END;

CREATE TRIGGER target_manifest_members_occupied BEFORE INSERT ON release_seoul_target_manifest_members WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_members WHERE generation=NEW.generation AND (space_id=NEW.space_id OR ordinal=NEW.ordinal)) BEGIN SELECT RAISE(ABORT,'manifest durable identity occupied'); END;
CREATE TRIGGER target_manifest_members_immutable BEFORE UPDATE ON release_seoul_target_manifest_members BEGIN SELECT RAISE(ABORT,'manifest durable row immutable'); END;
CREATE TRIGGER target_manifest_members_retained BEFORE DELETE ON release_seoul_target_manifest_members BEGIN SELECT RAISE(ABORT,'manifest durable row retained'); END;

CREATE TRIGGER target_manifest_pages_occupied BEFORE INSERT ON release_seoul_target_manifest_pages WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_pages WHERE generation=NEW.generation AND phase=NEW.phase AND page_no=NEW.page_no) BEGIN SELECT RAISE(ABORT,'manifest durable identity occupied'); END;
CREATE TRIGGER target_manifest_pages_immutable BEFORE UPDATE ON release_seoul_target_manifest_pages BEGIN SELECT RAISE(ABORT,'manifest durable row immutable'); END;
CREATE TRIGGER target_manifest_pages_retained BEFORE DELETE ON release_seoul_target_manifest_pages BEGIN SELECT RAISE(ABORT,'manifest durable row retained'); END;

CREATE TRIGGER target_manifest_steps_occupied BEFORE INSERT ON release_seoul_target_manifest_steps WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps WHERE (generation=NEW.generation AND space_id=NEW.space_id) OR command_id=NEW.command_id) BEGIN SELECT RAISE(ABORT,'manifest durable identity occupied'); END;
CREATE TRIGGER target_manifest_steps_immutable BEFORE UPDATE ON release_seoul_target_manifest_steps BEGIN SELECT RAISE(ABORT,'manifest durable row immutable'); END;
CREATE TRIGGER target_manifest_steps_retained BEFORE DELETE ON release_seoul_target_manifest_steps BEGIN SELECT RAISE(ABORT,'manifest durable row retained'); END;

CREATE TRIGGER target_manifest_seals_occupied BEFORE INSERT ON release_seoul_target_manifest_seals WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=NEW.generation) BEGIN SELECT RAISE(ABORT,'manifest durable identity occupied'); END;
CREATE TRIGGER target_manifest_seals_immutable BEFORE UPDATE ON release_seoul_target_manifest_seals BEGIN SELECT RAISE(ABORT,'manifest durable row immutable'); END;
CREATE TRIGGER target_manifest_seals_retained BEFORE DELETE ON release_seoul_target_manifest_seals BEGIN SELECT RAISE(ABORT,'manifest durable row retained'); END;

CREATE TRIGGER target_manifest_completions_occupied BEFORE INSERT ON release_seoul_target_manifest_completions WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=NEW.generation) BEGIN SELECT RAISE(ABORT,'manifest durable identity occupied'); END;
CREATE TRIGGER target_manifest_completions_immutable BEFORE UPDATE ON release_seoul_target_manifest_completions BEGIN SELECT RAISE(ABORT,'manifest durable row immutable'); END;
CREATE TRIGGER target_manifest_completions_retained BEFORE DELETE ON release_seoul_target_manifest_completions BEGIN SELECT RAISE(ABORT,'manifest durable row retained'); END;

CREATE TRIGGER target_manifest_cancellations_occupied BEFORE INSERT ON release_seoul_target_manifest_cancellations WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations WHERE generation=NEW.generation OR cancellation_id=NEW.cancellation_id) BEGIN SELECT RAISE(ABORT,'manifest durable identity occupied'); END;
CREATE TRIGGER target_manifest_cancellations_immutable BEFORE UPDATE ON release_seoul_target_manifest_cancellations BEGIN SELECT RAISE(ABORT,'manifest durable row immutable'); END;
CREATE TRIGGER target_manifest_cancellations_retained BEFORE DELETE ON release_seoul_target_manifest_cancellations BEGIN SELECT RAISE(ABORT,'manifest durable row retained'); END;

CREATE TRIGGER target_manifest_control_insert BEFORE INSERT ON release_seoul_target_manifest_control BEGIN SELECT RAISE(ABORT,'manifest control occupied'); END;
CREATE TRIGGER target_manifest_control_retained BEFORE DELETE ON release_seoul_target_manifest_control BEGIN SELECT RAISE(ABORT,'manifest control retained'); END;
CREATE TRIGGER target_manifest_control_advance BEFORE UPDATE ON release_seoul_target_manifest_control WHEN NEW.singleton IS NOT OLD.singleton OR NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a JOIN release_seoul_target_manifests h ON h.generation=a.generation AND h.manifest_id=a.manifest_id WHERE a.operation='publish' AND a.expected_generation IS OLD.current_generation AND a.observed_generation IS OLD.current_generation AND NEW.current_generation=a.generation AND h.expected_generation IS OLD.current_generation)
 BEGIN SELECT RAISE(ABORT,'manifest control requires exact predecessor'); END;
CREATE TRIGGER target_manifest_attempt_fresh BEFORE INSERT ON release_seoul_target_manifest_attempt WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt LIMIT 1) OR EXISTS(SELECT 1 FROM release_seoul_target_attempt LIMIT 1) BEGIN SELECT RAISE(ABORT,'manifest staging is not empty'); END;
CREATE TRIGGER target_manifest_attempt_immutable BEFORE UPDATE ON release_seoul_target_manifest_attempt BEGIN SELECT RAISE(ABORT,'manifest operation witness immutable'); END;
CREATE TRIGGER target_manifest_attempt_context BEFORE INSERT ON release_seoul_target_manifest_attempt BEGIN
 SELECT (CASE WHEN NEW.observed_generation IS NOT (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) THEN RAISE(ABORT,'manifest observed generation changed') END);
 SELECT (CASE WHEN NEW.operation='publish' AND (NEW.expected_generation IS NOT (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) OR NEW.generation IS NOT coalesce(NEW.expected_generation,0)+1 OR coalesce(NEW.expected_generation,0)>=9007199254740991) THEN RAISE(ABORT,'manifest predecessor conflict') END);
 SELECT (CASE WHEN NEW.operation<>'publish' AND NOT (NEW.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=NEW.generation AND h.manifest_id=NEW.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=NEW.generation)) THEN RAISE(ABORT,'manifest generation not current') END);
 SELECT (CASE WHEN NEW.operation IN ('page','apply','verify','seal','complete') AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=NEW.generation) THEN RAISE(ABORT,'manifest already complete') END);
 SELECT (CASE WHEN NEW.operation='page' AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=NEW.generation) THEN RAISE(ABORT,'manifest inventory sealed') END);
 SELECT (CASE WHEN NEW.operation IN ('apply','verify','complete') AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=NEW.generation) THEN RAISE(ABORT,'manifest inventory not sealed') END);
 SELECT (CASE WHEN NEW.operation='apply' AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps s WHERE s.generation=NEW.generation AND s.space_id=NEW.space_id AND s.command_id=NEW.command_id AND s.expected_revision IS NEW.expected_revision AND s.selected=NEW.selected AND s.operator_reference=NEW.operator_reference) THEN RAISE(ABORT,'manifest step not exact') END);
 SELECT (CASE WHEN NEW.operation='apply' AND EXISTS(SELECT 1 FROM release_seoul_target_receipts WHERE command_id=NEW.command_id) THEN RAISE(ABORT,'manifest step already has immutable receipt') END);
 SELECT (CASE WHEN NEW.operation IN ('page','verify') AND NOT ((NEW.page_no=1 AND NEW.after_space_id IS NULL AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_pages WHERE generation=NEW.generation AND phase=NEW.phase)) OR EXISTS(SELECT 1 FROM release_seoul_target_manifest_pages p WHERE p.generation=NEW.generation AND p.phase=NEW.phase AND p.page_no=NEW.page_no-1 AND p.last_space_id=NEW.after_space_id AND p.terminal=0 AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_pages q WHERE q.generation=p.generation AND q.phase=p.phase AND q.page_no=NEW.page_no))) THEN RAISE(ABORT,'manifest page predecessor conflict') END);
END;
CREATE TRIGGER target_manifest_header_context BEFORE INSERT ON release_seoul_target_manifests BEGIN
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='publish' AND a.generation=NEW.generation AND a.manifest_id=NEW.manifest_id AND a.expected_generation IS NEW.expected_generation AND a.observed_generation IS (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND a.input_bytes=NEW.manifest_bytes AND a.manifest_sha256=NEW.manifest_sha256 AND a.set_sha256=NEW.set_sha256 AND a.decided_at=NEW.published_at) THEN RAISE(ABORT,'manifest publication witness required') END);
 SELECT (CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.manifest_bytes,'$.spaceIds') j WHERE j.type<>'text' OR NOT (typeof(j.value)='text' AND length(CAST(j.value AS BLOB)) BETWEEN 1 AND 128 AND length(CAST(j.value AS BLOB))=length(j.value) AND substr(j.value,1,1) GLOB '[A-Za-z0-9]' AND j.value NOT GLOB '*[^A-Za-z0-9._:-]*') OR CAST(j.key AS INTEGER)>0 AND j.value<=json_extract(NEW.manifest_bytes,'$.spaceIds['||(CAST(j.key AS INTEGER)-1)||']')) THEN RAISE(ABORT,'manifest member list not canonical') END);
END;
CREATE TRIGGER target_manifest_member_context BEFORE INSERT ON release_seoul_target_manifest_members WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a JOIN release_seoul_target_manifests h ON h.generation=a.generation WHERE a.operation='publish' AND a.generation=NEW.generation AND a.input_bytes=h.manifest_bytes AND json_extract(h.manifest_bytes,'$.spaceIds['||(NEW.ordinal-1)||']')=NEW.space_id) BEGIN SELECT RAISE(ABORT,'manifest member requires exact publication'); END;

CREATE TRIGGER target_manifest_page_context BEFORE INSERT ON release_seoul_target_manifest_pages WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation=CASE WHEN NEW.phase='verify' THEN 'verify' ELSE 'page' END AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND a.generation=NEW.generation AND a.phase=NEW.phase AND a.page_no=NEW.page_no AND a.after_space_id IS NEW.after_space_id AND a.decided_at=NEW.observed_at AND NEW.row_count=json_array_length(a.input_bytes)
 AND NEW.last_space_id IS CASE WHEN NEW.row_count=0 THEN NULL ELSE json_extract(a.input_bytes,'$['||(NEW.row_count-1)||'].spaceId') END
 AND NEW.cumulative_count=NEW.row_count+coalesce((SELECT cumulative_count FROM release_seoul_target_manifest_pages p WHERE p.generation=NEW.generation AND p.phase=NEW.phase AND p.page_no=NEW.page_no-1),0)) BEGIN SELECT RAISE(ABORT,'manifest page requires exact witness'); END;
CREATE TRIGGER target_manifest_step_context BEFORE INSERT ON release_seoul_target_manifest_steps WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a JOIN release_seoul_target_manifests h ON h.generation=a.generation JOIN json_each(a.input_bytes) j JOIN release_seoul_target_manifest_pages p ON p.generation=a.generation AND p.phase=a.phase AND p.page_no=a.page_no WHERE a.operation='page' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND a.generation=NEW.generation AND a.phase=NEW.page_phase AND a.page_no=NEW.page_no AND h.operator_reference=NEW.operator_reference AND json_extract(j.value,'$.spaceId')=NEW.space_id AND json_extract(j.value,'$.commandId')=NEW.command_id AND json_extract(j.value,'$.expectedRevision') IS NEW.expected_revision
 AND NEW.expected_revision IS (SELECT revision FROM release_seoul_targets WHERE space_id=NEW.space_id) AND (NEW.page_phase='desired' AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation AND m.space_id=NEW.space_id) OR NEW.page_phase='omitted' AND EXISTS(SELECT 1 FROM release_seoul_targets t WHERE t.space_id=NEW.space_id AND t.selected=1) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation AND m.space_id=NEW.space_id))) BEGIN SELECT RAISE(ABORT,'manifest step requires exact inventory'); END;
CREATE TRIGGER target_manifest_seal_context BEFORE INSERT ON release_seoul_target_manifest_seals WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='seal' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND a.generation=NEW.generation AND a.decided_at=NEW.sealed_at AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h JOIN release_seoul_target_manifest_pages d ON d.generation=h.generation AND d.phase='desired' AND d.page_no=NEW.desired_terminal_page AND d.terminal=1 JOIN release_seoul_target_manifest_pages o ON o.generation=h.generation AND o.phase='omitted' AND o.page_no=NEW.omitted_terminal_page AND o.terminal=1 WHERE h.generation=NEW.generation AND d.cumulative_count=NEW.desired_count AND d.cumulative_count=h.desired_count AND o.cumulative_count=NEW.omitted_count)) BEGIN SELECT RAISE(ABORT,'manifest seal requires both terminal inventories'); END;
CREATE TRIGGER target_manifest_completion_context BEFORE INSERT ON release_seoul_target_manifest_completions WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='complete' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND a.generation=NEW.generation AND a.decided_at=NEW.completed_at AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h JOIN release_seoul_target_manifest_seals z ON z.generation=h.generation JOIN release_seoul_target_manifest_pages p ON p.generation=h.generation AND p.phase='verify' AND p.page_no=NEW.verified_terminal_page AND p.terminal=1 WHERE h.generation=NEW.generation AND h.manifest_sha256=NEW.manifest_sha256 AND h.set_sha256=NEW.set_sha256 AND p.cumulative_count=z.total_count AND NEW.step_count=z.total_count)) BEGIN SELECT RAISE(ABORT,'manifest completion requires exact verified inventory'); END;
CREATE TRIGGER target_manifest_cancellation_context BEFORE INSERT ON release_seoul_target_manifest_cancellations WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='cancel' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND a.generation=NEW.generation AND a.cancellation_id=NEW.cancellation_id AND a.operator_reference=NEW.operator_reference AND a.decided_at=NEW.cancelled_at) BEGIN SELECT RAISE(ABORT,'manifest cancellation requires exact witness'); END;

-- These independent BEFORE guards never depend on same-timing trigger order.
CREATE TRIGGER target_manifest_target_attempt_context BEFORE INSERT ON release_seoul_target_attempt WHEN ((SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) IS NOT NULL OR EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt LIMIT 1)) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='apply' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND a.command_id=step.command_id AND a.space_id=step.space_id AND a.expected_revision IS step.expected_revision AND a.selected=step.selected AND a.operator_reference=step.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=a.generation) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=a.generation) AND a.command_id=NEW.command_id AND a.space_id=NEW.space_id AND a.expected_revision IS NEW.expected_revision AND a.selected=NEW.selected AND a.operator_reference=NEW.operator_reference) BEGIN SELECT RAISE(ABORT,'target requires current manifest step'); END;
CREATE TRIGGER target_manifest_source_context BEFORE INSERT ON release_seoul_authority_changes WHEN NEW.stream_kind='target' AND (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='apply' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND a.command_id=step.command_id AND a.space_id=step.space_id AND a.expected_revision IS step.expected_revision AND a.selected=step.selected AND a.operator_reference=step.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=a.generation) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_attempt s WHERE a.command_id=s.command_id AND a.space_id=s.space_id AND a.expected_revision IS s.expected_revision AND a.selected=s.selected AND a.operator_reference=s.operator_reference AND s.eligible=1 AND s.decision='changed' AND NEW.source_command_id=s.command_id AND NEW.stream_key=s.space_id AND NEW.event_id=s.new_event_id AND NEW.created_at=s.decided_at AND NEW.record_bytes=json_object('version',3,'kind','target-source','spaceId',s.space_id,'selected',json(CASE WHEN s.selected=1 THEN 'true' ELSE 'false' END),'changedAtMs',s.decided_at,'origin',json_object('kind','command','commandType','target-reconcile','receiptId',s.command_id),'effect',json(CASE WHEN s.selected=1 THEN json_object('type','entity-head','disposition','changed') ELSE json_object('type','entity-negative','entityKind','target