CREATE TRIGGER target_manifest_receipt_context BEFORE INSERT ON release_seoul_target_receipts WHEN (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='apply' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND a.command_id=step.command_id AND a.space_id=step.space_id AND a.expected_revision IS step.expected_revision AND a.selected=step.selected AND a.operator_reference=step.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=a.generation) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=a.generation) AND a.command_id=NEW.command_id AND a.space_id=NEW.space_id AND a.expected_revision IS NEW.expected_revision AND a.selected=NEW.selected AND a.operator_reference=NEW.operator_reference AND EXISTS(SELECT 1 FROM release_seoul_target_attempt s WHERE a.command_id=s.command_id AND a.space_id=s.space_id AND a.expected_revision IS s.expected_revision AND a.selected=s.selected AND a.operator_reference=s.operator_reference AND s.eligible=1 AND s.decision=NEW.outcome AND s.decided_at=NEW.decided_at)) BEGIN SELECT RAISE(ABORT,'target receipt requires current manifest step'); END;
CREATE TRIGGER target_manifest_head_insert_context BEFORE INSERT ON release_seoul_authority_heads WHEN NEW.stream_kind='target' AND (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='apply' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND a.command_id=step.command_id AND a.space_id=step.space_id AND a.expected_revision IS step.expected_revision AND a.selected=step.selected AND a.operator_reference=step.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=a.generation) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_attempt s WHERE a.command_id=s.command_id AND a.space_id=s.space_id AND a.expected_revision IS s.expected_revision AND a.selected=s.selected AND a.operator_reference=s.operator_reference AND s.eligible=1 AND s.decision='changed' AND NEW.stream_key=s.space_id AND NEW.event_id=s.new_event_id AND NEW.payload_sha256 IS NULL AND EXISTS(SELECT 1 FROM release_seoul_authority_changes c WHERE c.revision=NEW.revision AND c.source_command_id=s.command_id AND c.stream_kind='target' AND c.stream_key=s.space_id AND c.event_id=s.new_event_id AND c.created_at=s.decided_at))) BEGIN SELECT RAISE(ABORT,'target head requires current manifest step'); END;
CREATE TRIGGER target_manifest_head_update_context BEFORE UPDATE ON release_seoul_authority_heads WHEN NEW.stream_kind='target' AND (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) IS NOT NULL AND NOT (EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='apply' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND a.command_id=step.command_id AND a.space_id=step.space_id AND a.expected_revision IS step.expected_revision AND a.selected=step.selected AND a.operator_reference=step.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=a.generation) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_attempt s WHERE a.command_id=s.command_id AND a.space_id=s.space_id AND a.expected_revision IS s.expected_revision AND a.selected=s.selected AND a.operator_reference=s.operator_reference AND s.eligible=1 AND s.decision='changed' AND NEW.stream_key=s.space_id AND NEW.event_id=s.new_event_id AND NEW.payload_sha256 IS NULL AND EXISTS(SELECT 1 FROM release_seoul_authority_changes c WHERE c.revision=NEW.revision AND c.source_command_id=s.command_id AND c.stream_kind='target' AND c.stream_key=s.space_id AND c.event_id=s.new_event_id AND c.created_at=s.decided_at))) OR (OLD.revision=NEW.revision AND OLD.event_id=NEW.event_id AND OLD.stream_kind=NEW.stream_kind AND OLD.stream_key=NEW.stream_key AND OLD.payload_sha256 IS NULL AND NEW.payload_sha256 IS NOT NULL AND EXISTS(SELECT 1 FROM release_seoul_target_preparation_stage w JOIN release_seoul_authority_changes c ON c.revision=w.revision AND c.source_command_id=w.source_command_id AND c.stream_kind=w.stream_kind AND c.stream_key=w.stream_key AND c.event_id=w.event_id AND c.record_bytes=w.record_bytes AND c.created_at=w.created_at JOIN release_seoul_prepared_sources p ON p.revision=c.revision AND p.event_id=c.event_id AND p.source_sha256=w.source_sha256 AND p.transport_sha256=w.transport_sha256 JOIN release_seoul_projection_events e ON e.event_id=c.event_id AND e.source_revision=c.revision AND e.event_kind='head' AND e.stream_kind='target' AND e.stream_key=c.stream_key AND e.space_id IS NULL AND e.snapshot_seq IS NULL AND e.issued_at IS NULL AND e.expires_at IS NULL AND e.source_sha256=p.source_sha256 AND e.payload_sha256=p.transport_sha256 AND e.payload_bytes=w.payload_bytes JOIN release_seoul_projection_deliveries d ON d.event_id=e.event_id WHERE w.eligible=1 AND w.revision=NEW.revision AND w.event_id=NEW.event_id AND w.stream_key=NEW.stream_key AND NEW.payload_sha256=w.source_sha256))) BEGIN SELECT RAISE(ABORT,'target head requires exact current context'); END;

CREATE TRIGGER target_manifest_target_insert_context BEFORE INSERT ON release_seoul_targets WHEN (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='apply' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND a.command_id=step.command_id AND a.space_id=step.space_id AND a.expected_revision IS step.expected_revision AND a.selected=step.selected AND a.operator_reference=step.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=a.generation) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_attempt s WHERE a.command_id=s.command_id AND a.space_id=s.space_id AND a.expected_revision IS s.expected_revision AND a.selected=s.selected AND a.operator_reference=s.operator_reference AND s.eligible=1 AND s.decision='changed' AND NEW.space_id=s.space_id AND NEW.selected=s.selected AND s.prior_state='absent' AND NOT EXISTS(SELECT 1 FROM release_seoul_targets WHERE space_id=NEW.space_id) AND EXISTS(SELECT 1 FROM release_seoul_target_receipts r WHERE s.command_id=r.command_id AND s.space_id=r.space_id AND s.expected_revision IS r.expected_revision AND s.selected=r.selected AND s.operator_reference=r.operator_reference AND r.outcome='changed' AND r.resulting_revision=NEW.revision AND r.resulting_event_id=s.new_event_id AND r.decided_at=s.decided_at))) BEGIN SELECT RAISE(ABORT,'target state requires current manifest step'); END;

CREATE TRIGGER target_manifest_target_update_context BEFORE UPDATE ON release_seoul_targets WHEN (SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='apply' AND a.generation=(SELECT current_generation FROM release_seoul_target_manifest_control WHERE singleton=1) AND EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=a.generation AND h.manifest_id=a.manifest_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_cancellations x WHERE x.generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND a.command_id=step.command_id AND a.space_id=step.space_id AND a.expected_revision IS step.expected_revision AND a.selected=step.selected AND a.operator_reference=step.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_manifest_seals WHERE generation=a.generation) AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_completions WHERE generation=a.generation) AND EXISTS(SELECT 1 FROM release_seoul_target_attempt s WHERE a.command_id=s.command_id AND a.space_id=s.space_id AND a.expected_revision IS s.expected_revision AND a.selected=s.selected AND a.operator_reference=s.operator_reference AND s.eligible=1 AND s.decision='changed' AND NEW.space_id=s.space_id AND NEW.selected=s.selected AND s.prior_state='present' AND OLD.space_id=s.space_id AND OLD.revision=s.prior_revision AND OLD.selected=s.prior_selected AND NEW.revision>OLD.revision AND EXISTS(SELECT 1 FROM release_seoul_target_receipts r WHERE s.command_id=r.command_id AND s.space_id=r.space_id AND s.expected_revision IS r.expected_revision AND s.selected=r.selected AND s.operator_reference=r.operator_reference AND r.outcome='changed' AND r.resulting_revision=NEW.revision AND r.resulting_event_id=s.new_event_id AND r.decided_at=s.decided_at))) BEGIN SELECT RAISE(ABORT,'targ