CREATE TRIGGER target_manifest_page_desired_first BEFORE INSERT ON release_seoul_target_manifest_pages WHEN NEW.phase='desired' AND NEW.after_space_id IS NULL BEGIN
 SELECT (CASE WHEN (SELECT count(*) FROM (SELECT m.space_id FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation ORDER BY m.space_id LIMIT 33))<>NEW.row_count+(1-NEW.terminal) THEN RAISE(ABORT,'manifest exact next page count changed') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.generation=NEW.generation AND a.phase=NEW.phase AND a.page_no=NEW.page_no AND (SELECT json_group_array(json_extract(j.value,'$.spaceId')) FROM json_each(a.input_bytes) j)=(SELECT json_group_array(space_id) FROM (SELECT m.space_id FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation ORDER BY m.space_id LIMIT 32))) THEN RAISE(ABORT,'manifest exact next page members changed') END);
 END;

