 SELECT (CASE WHEN (SELECT count(*) FROM (SELECT t.space_id FROM release_seoul_targets t INDEXED BY release_seoul_targets_selected_space WHERE t.selected=1 AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation AND m.space_id=t.space_id) ORDER BY t.space_id LIMIT 33))<>NEW.row_count+(1-NEW.terminal) THEN RAISE(ABORT,'manifest exact next page count changed') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.generation=NEW.generation AND a.phase=NEW.phase AND a.page_no=NEW.page_no AND (SELECT json_group_array(json_extract(j.value,'$.spaceId')) FROM json_each(a.input_bytes) j)=(SELECT json_group_array(space_id) FROM (SELECT t.space_id FROM release_seoul_targets t INDEXED BY release_seoul_targets_selected_space WHERE t.selected=1 AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation AND m.space_id=t.space_id) ORDER BY t.space_id LIMIT 32))) THEN RAISE(ABORT,'manifest exact next page members changed') END);
 END;

CREATE TRIGGER target_manifest_page_omitted_after BEFORE INSERT ON release_seoul_target_manifest_pages WHEN NEW.phase='omitted' AND NEW.after_space_id IS NOT NULL BEGIN
 SELECT (CASE WHEN (SELECT count(*) FROM (SELECT t.space_id FROM release_seoul_targets t INDEXED BY release_seoul_targets_selected_space WHERE t.selected=1 AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation AND m.space_id=t.space_id) AND t.space_id>NEW.after_space_id ORDER BY t.space_id LIMIT 33))<>NEW.row_count+(1-NEW.terminal) THEN RAISE(ABORT,'manifest exact next page count changed') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.generation=NEW.generation AND a.phase=NEW.phase AND a.page_no=NEW.page_no AND (SELECT json_group_array(json_extract(j.value,'$.spaceId')) FROM json_each(a.input_bytes) j)=(SELECT json_group_array(space_id) FROM (SELECT t.space_id FROM release_seoul_targets t INDEXED BY release_seoul_targets_selected_space WHERE t.selected=1 AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_members m WHERE m.generation=NEW.generation AND m.space_id=t.space_id) AND t.space_id>NEW.after_space_id ORDER BY t.space_id LIMIT 32))) THEN RAISE(ABORT,'manifest exact next page members changed') END);
 END;

CREATE TRIGGER target_manifest_page_verify_first BEFORE INSERT ON release_seoul_target_manifest_pages WHEN NEW.phase='verify' AND NEW.after_space_id IS NULL BEGIN
 SELECT (CASE WHEN (SELECT count(*) FROM (SELECT s.space_id FROM release_seoul_target_manifest_steps s WHERE s.generation=NEW.generation ORDER BY s.space_id LIMIT 33))<>NEW.row_count+(1-NEW.terminal) THEN RAISE(ABORT,'manifest exact next page count changed') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.generation=NEW.generation AND a.phase=NEW.phase AND a.page_no=NEW.page_no AND (SELECT json_group_array(json_extract(j.value,'$.spaceId')) FROM json_each(a.input_bytes) j)=(SELECT json_group_array(space_id) FROM (SELECT s.space_id FROM release_seoul_target_manifest_steps s WHERE s.generation=NEW.generation ORDER BY s.space_id LIMIT 32))) THEN RAISE(ABORT,'manifest exact next page members changed') END);
 END;

CREATE TRIGGER target_manifest_page_verify_after BEFORE INSERT ON release_seoul_target_manifest_pages WHEN NEW.phase='verify' AND NEW.after_space_id IS NOT NULL BEGIN
 SELECT (CASE WHEN (SELECT count(*) FROM (SELECT s.space_id FROM release_seoul_target_manifest_steps s WHERE s.generation=NEW.generation AND s.space_id>NEW.after_space_id ORDER BY s.space_id LIMIT 33))<>NEW.row_count+(1-NEW.terminal) THEN RAISE(ABORT,'manifest exact next page count changed') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.generation=NEW.generation AND a.phase=NEW.phase AND a.page_no=NEW.page_no AND (SELECT json_group_array(json_extract(j.value,'$.spaceId')) FROM json_each(a.input_bytes) j)=(SELECT json_group_array(space_id) FROM (SELECT s.space_id FROM release_seoul_target_manifest_steps s WHERE s.generation=NEW.generation AND s.space_id>NEW.after_space_id ORDER BY s.space_id LIMIT 32))) THEN RAISE(ABORT,'manifest exact next page members changed') END);
 END;

CREATE TRIGGER target_manifest_page_previous_children BEFORE INSERT ON release_seoul_target_manifest_pages WHEN NEW.page_no>1 AND NEW.phase IN ('desired','omitted') AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_pages p WHERE p.generation=NEW.generation AND p.phase=NEW.phase AND p.page_no=NEW.page_no-1 AND (SELECT count(*) FROM release_seoul_target_manifest_steps s WHERE s.generation=p.generation AND s.page_phase=p.phase AND s.page_no=p.page_no)=p.row_count) BEGIN SELECT RAISE(ABORT,'manifest previous page children incomplete'); END;
CREATE TRIGGER target_manifest_seal_terminal_children BEFORE INSERT ON release_seoul_target_manifest_seals WHEN EXISTS(SELECT 1 FROM release_seoul_target_manifest_pages p WHERE p.generation=NEW.generation AND (p.phase='desired' AND p.page_no=NEW.desired_terminal_page OR p.phase='omitted' AND p.page_no=NEW.omitted_terminal_page) AND (SELECT count(*) FROM release_seoul_target_manifest_steps s WHERE s.generation=p.generation AND s.page_phase=p.phase AND s.page_no=p.page_no)<>p.row_count) BEGIN SELECT RAISE(ABORT,'manifest terminal page children incomplete'); END;

CREATE TRIGGER target_manifest_completion_selected BEFORE INSERT ON release_seoul_target_manifest_completions WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifests h WHERE h.generation=NEW.generation AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_members m WHERE m.generation=h.generation AND NOT EXISTS(SELECT 1 FROM release_seoul_targets t WHERE t.space_id=m.space_id AND t.selected=1)) AND (SELECT count(*) FROM (SELECT space_id FROM release_seoul_targets INDEXED BY release_seoul_targets_selected_space WHERE selected=1 ORDER BY space_id LIMIT 1025))=h.desired_count) BEGIN SELECT RAISE(ABORT,'manifest actual selected set is not exact'); END;

CREATE TRIGGER target_manifest_verify_exact_proof BEFORE INSERT ON release_seoul_target_manifest_pages WHEN NEW.phase='verify' AND NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a WHERE a.operation='verify' AND a.generation=NEW.generation AND a.phase=NEW.phase AND a.page_no=NEW.page_no AND NOT EXISTS(SELECT 1 FROM (SELECT json_extract(j.value,'$.commandId') command_id,json_extract(j.value,'$.spaceId') space_id,json_extract(j.value,'$.expectedRevision') expected_revision,json_extract(j.value,'$.selected') selected,json_extract(j.value,'$.operatorReference') operator_reference,json_extract(j.value,'$.prior_revision') prior_revision,json_extract(j.value,'$.prior_selected') prior_selected,json_extract(j.value,'$.prior_event_id') prior_event_id,json_extract(j.value,'$.prior_source_command_id') prior_source_command_id,json_extract(j.value,'$.prior_record_bytes') prior_record_bytes,json_extract(j.value,'$.prior_created_at') prior_created_at,json_extract(j.value,'$.prior_source_sha256') prior_source_sha256,json_extract(j.value,'$.prior_transport_sha256') prior_transport_sha256,json_extract(j.value,'$.prior_payload_bytes') prior_payload_bytes,json_extract(j.value,'$.prior_changed_receipt_bytes') prior_changed_receipt_bytes,json_extract(j.value,'$.receipt_bytes') receipt_bytes FROM json_each(a.input_bytes) j) s WHERE NOT (EXISTS(SELECT 1 FROM release_seoul_target_manifest_steps step WHERE step.generation=a.generation AND step.space_id=s.space_id AND step.command_id=s.command_id AND step.expected_revision IS s.expected_revision AND step.selected=s.selected AND step.operator_reference=s.operator_reference) AND EXISTS(SELECT 1 FROM release_seoul_target_receipts r WHERE r.command_id=s.command_id AND r.space_id=s.space_id AND r.expected_revision IS s.expected_revision AND r.selected=s.selected AND r.operator_reference=s.operator_reference AND json_object('commandId',r.command_id,'spaceId',r.space_id,'expectedRevision',r.expected_revision,'selected',json(CASE WHEN r.selected=1 THEN 'true' ELSE 'false' END),'operatorReference',r.operator_reference,'outcome',r.outcome,'resultingRevision',r.resulting_revision,'resultingEventId',r.resulting_event_id,'decidedAtMs',r.decided_at)=s.receipt_bytes AND EXISTS(SELECT 1 FROM release_seoul_authority_changes c JOIN release_seoul_target_receipts original ON original.command_id=c.source_command_id
 WHERE c.revision=r.resulting_revision AND c.event_id=r.resulting_event_id AND c.stream_kind='target' AND c.stream_key=r.space_id
 AND c.record_bytes=json_object('version',3,'kind','target-source','spaceId',r.space_id,'selected',json(CASE WHEN r.selected=1 THEN 'true' ELSE 'false' END),'changedAtMs',c.created_at,'origin',json_object('kind','command','commandType','target-reconcile','receiptId',c.source_command_id),'effect',json(CASE WHEN r.selected=1 THEN json_object('type','entity-head','disposition','changed') ELSE json_object('type','entity-negative','entityKind','target','entityId',r.space_id,'state','removed','occurredAtMs',c.created_at) END))
 AND original.outcome='changed' AND original.space_id=r.space_id AND original.selected=r.selected AND original.resulting_revision=c.revision AND original.resulting_event_id=c.event_id AND original.decided_at=c.created_at
 AND ((r.outcome='changed' AND r.command_id=c.source_command_id AND r.decided_at=c.created_at AND (r.expected_revision IS NULL OR r.expected_revision<c.revision))
 OR (r.outcome='unchanged' AND r.expected_revision=c.revision AND r.command_id<>c.source_command_id)))
 AND r.resulting_revision=s.prior_revision AND r.resulting_event_id=s.prior_event_id AND r.selected=s.prior_selected AND EXISTS(SELECT 1 FROM release_seoul_targets t JOIN release_seoul_authority_heads h ON h.stream_kind='target' AND h.stream_key=t.space_id AND h.revision=t.revision JOIN release_seoul_authority_changes c ON c.revision=t.revision AND c.event_id=h.event_id JOIN release_seoul_target_receipts original ON original.command_id=c.source_command_id
 WHERE t.space_id=s.space_id AND t.revision=s.prior_revision AND t.selected=s.prior_selected AND c.source_command_id=s.prior_source_command_id AND c.stream_kind='target' AND c.stream_key=s.space_id AND c.event_id=s.prior_event_id AND c.record_bytes=s.prior_record_bytes AND c.created_at=s.prior_created_at
 AND original.outcome='changed' AND original.resulting_revision=c.revision AND original.resulting_event_id=c.event_id AND original.space_id=t.space_id AND original.selected=t.selected AND original.decided_at=c.created_at AND json_object('commandId',original.command_id,'spaceId',original.space_id,'expectedRevision',original.expected_revision,'selected',json(CASE WHEN original.selected=1 THEN 'true' ELSE 'false' END),'operatorReference',original.operator_reference,'outcome',original.outcome,'resultingRevision',original.resulting_revision,'resultingEventId',original.resulting_event_id,'decidedAtMs',original.decided_at)=s.prior_changed_receipt_bytes
 AND (h.payload_sha256 IS NULL OR (typeof(h.payload_sha256)='text' AND length(CAST(h.payload_sha256 AS BLOB))=64 AND length(h.payload_sha256)=64 AND h.payload_sha256 NOT GLOB '*[^0-9a-f]*')) AND NOT EXISTS(SELECT 1 FROM release_seoul_prepared_sources current_prepared WHERE current_prepared.revision=c.revision AND NOT ((current_prepared.source_sha256 IS NULL OR (typeof(current_prepared.source_sha256)='text' AND length(CAST(current_prepared.source_sha256 AS BLOB))=64 AND length(current_prepared.source_sha256)=64 AND current_prepared.source_sha256 NOT GLOB '*[^0-9a-f]*')) AND (current_prepared.transport_sha256 IS NULL OR (typeof(current_prepared.transport_sha256)='text' AND length(CAST(current_prepared.transport_sha256 AS BLOB))=64 AND length(current_prepared.transport_sha256)=64 AND current_prepared.transport_sha256 NOT GLOB '*[^0-9a-f]*'))))
 AND (h.payload_sha256 IS NULL OR (h.payload_sha256=s.prior_source_sha256 AND EXISTS(SELECT 1 FROM release_seoul_prepared_sources p JOIN release_seoul_projection_events e ON e.event_id=p.event_id JOIN release_seoul_projection_deliveries delivery ON delivery.event_id=e.event_id
 WHERE p.revision=c.revision AND p.event_id=c.event_id AND p.source_sha256=s.prior_source_sha256 AND p.transport_sha256=s.prior_transport_sha256 AND e.source_revision=c.revision AND e.event_kind='head' AND e.stream_kind='target' AND e.stream_key=s.space_id AND e.source_sha256=p.source_sha256 AND e.payload_sha256=p.transport_sha256 AND e.payload_bytes=s.prior_payload_bytes AND e.space_id IS NULL AND e.snapshot_seq IS NULL AND e.issued_at IS NULL AND e.expires_at IS NULL)))))))) BEGIN SELECT RAISE(ABORT,'manifest verification requires exact current and historical proof'); END;

CREATE TRIGGER target_manifest_step_current_proof BEFORE INSERT ON release_seoul_target_manifest_steps WHEN NOT EXISTS(SELECT 1 FROM release_seoul_target_manifest_attempt a JOIN json_each(a.input_bytes) j WHERE a.operation='page' AND a.generation=NEW.generation AND a.phase=NEW.page_phase AND a.page_no=NEW.page_no AND json_extract(j.value,'$.spaceId')=NEW.space_id AND ((json_extract(j.value,'$.prior_state')='absent' AND NEW.expected_revision IS NULL AND NOT EXISTS(SELECT 1 FROM release_seoul_targets WHERE space_id=NEW.space_id) AND NOT EXISTS(SELECT 1 FROM release_seoul_authority_heads WHERE stream_kind='target' AND stream_key=NEW.space_id)) OR (json_extract(j.value,'$.prior_state')='present' AND EXISTS(SELECT 1 FROM release_seoul_targets t JOIN release_seoul_authority_heads h ON h.stream_kind='target' AND h.stream_key=t.space_id AND h.revision=t.revision JOIN release_seoul_authority_changes c ON c.revision=t.revision AND c.event_id=h.event_id JOIN release_seoul_target_receipts o ON o.command_id=c.source_command_id WHERE (h.payload_sha256 IS NULL OR (typeof(h.payload_sha256)='text' AND length(CAST(h.payload_sha256 AS BLOB))=64 AND length(h.payload_sha256)=64 AND h.payload_sha256 NOT GLOB '*[^0-9a-f]*')) AND NOT EXISTS(SELECT 1 FROM release_seoul_prepared_sources invalid WHERE invalid.revision=c.revision AND (NOT (typeof(invalid.source_sha256)='text' AND length(CAST(invalid.source_sha256 AS BLOB))=64 AND length(invalid.source_sha256)=64 AND invalid.source_sha256 NOT GLOB '*[^0-9a-f]*') OR NOT (typeof(invalid.transport_sha256)='text' AND length(CAST(invalid.transport_sha256 AS BLOB))=64 AND length(invalid.transport_sha256)=64 AND invalid.transport_sha256 NOT GLOB '*[^0-9a-f]*'))) AND t.space_id=NEW.space_id AND t.revision=NEW.expected_revision AND t.revision=json_extract(j.value,'$.prior_revision') AND t.selected=json_extract(j.value,'$.prior_selected') AND c.source_command_id=json_extract(j.value,'$.prior_source_command_id') AND c.stream_kind='target' AND c.stream_key=t.space_id AND c.event_id=json_extract(j.value,'$.prior_event_id') AND c.record_bytes=json_extract(j.value,'$.prior_record_bytes') AND c.created_at=json_extract(j.value,'$.prior_created_at') AND o.outcome='changed' AND o.resulting_revision=c.revision AND o.resulting_event_id=c.event_id AND o.space_id=t.space_id AND o.selected=t.selected AND o.decided_at=c.created_at AND json_object('commandId',o.command_id,'spaceId',o.space_id,'expectedRevision',o.expected_revision,'selected',json(CASE WHEN o.selected=1 THEN 'true' ELSE 'false' END),'operatorReference',o.operator_reference,'outcome',o.outcome,'resultingRevision',o.resulting_revision,'resultingEventId',o.resulting_event_id,'decidedAtMs',o.decided_at)=json_extract(j.value,'$.prior_changed_receipt_bytes') AND (h.payload_sha256 IS NULL OR h.payload_sha256=json_extract(j.value,'$.prior_source_sha256') AND EXISTS(SELECT 1 FROM release_seoul_prepared_sources p JOIN release_seoul_projection_events e ON e.event_id=p.event_id JOIN release_seoul_projection_deliveries d ON d.event_id=e.event_id WHERE p.revision=c.revision AND p.event_id=c.event_id AND p.source_sha256=json_extract(j.value,'$.prior_source_sha256') AND p.transport_sha256=json_extract(j.value,'$.prior_transport_sha256') AND e.source_revision=c.revision AND e.event_kind='head' AND e.stream_kind='target' AND e.stream_key=t.space_id AND e.space_id IS NULL AND e.snapshot_seq IS NULL AND e.issued_at IS NULL AND e.expires_at IS NULL AND e.source_sha256=p.source_sha256 AND e.payload_sha256=p.transport_sha256 AND e.payload_bytes=json_extract(j.value,'$.prior_payload_bytes'))))))) BEGIN SELECT RAISE(ABORT,'manifest step current source changed'); END;
CREATE TRIGGER target_manifest_attempt_page_shape BEFORE INSERT ON release_seoul_target_manifest_attempt WHEN NEW.operation IN ('page','verify') AND (NEW.phase IS NULL OR NEW.page_no IS NULL OR json_type(NEW.input_bytes)<>'array' OR json_array_length(NEW.input_bytes)>32 OR EXISTS(SELECT 1 FROM json_each(NEW.input_bytes) j WHERE j.type<>'object')) BEGIN SELECT RAISE(ABORT,'manifest page witness shape invalid'); END;

UPDATE release_meta SET version=35 WHERE version=34;
